#!/usr/bin/env bash

#------------------------------------------------------------------------------
# park.sh - park an issue for the user without an agent: label, comment, back to Triage.
# The steps of "Parking an issue for the user" in the project-board skill, as a script.
# Needs: gh (scope: repo), the board script of the project-board skill.
#------------------------------------------------------------------------------
set -euo pipefail

# shellcheck disable=SC1091  # lib.sh belongs to the project-board skill
source "$(dirname "$0")/../../project-board/scripts/lib.sh"

BOARD_SCRIPT=${BOARD_SCRIPT:-$(dirname "$0")/../../project-board/scripts/board.sh}
LABEL_PARKED="needs-info"
PARK_COLUMN="Triage"
AI_LINE="> *This was generated by AI (orchestrator).*"

usage() {
    cat <<USAGE
usage: park.sh <issue-number> <reason>
Adds the label $LABEL_PARKED (created if missing), comments the reason and moves the issue to $PARK_COLUMN,
which also clears the Agent field. The triager leaves such an issue alone until you remove the label.
USAGE
}

case "${1:-}" in
    --help|-h) usage; exit 0 ;;
esac
[ $# -eq 2 ] || usage_error
require_issue_numbers "$1"
[ -n "$2" ] || die "the reason must not be empty"

gh label create "$LABEL_PARKED" --force >/dev/null
gh issue edit "$1" --add-label "$LABEL_PARKED" >/dev/null
printf '%s\n%s\n' "$AI_LINE" "$2" | gh issue comment "$1" --body-file - >/dev/null
"$BOARD_SCRIPT" move "$1" "$PARK_COLUMN"
echo "parked: #$1 ($LABEL_PARKED, comment, $PARK_COLUMN)"
